function clockLabel(minute: number): string {
  const total = 17 * 60 + 30 + Math.max(0, Math.round(minute));
  return `${String(Math.floor(total / 60) % 24).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
