export function restaurantArenaLayout(width: number, height: number) {
  const scale = Math.min(width / 520, height / 740);
  const capped = Math.min(scale, 1.9);
  const compact = width < 460 || height < 420;
  const feedBeside = width >= 600;

  const topBar = { x: 0, y: 0, w: width, h: 60 };
