export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

const BASE_WIDTH = 520;
const BASE_HEIGHT = 740;
const SCALE_CAP = 1.9;
const COMPACT_WIDTH = 460;
const COMPACT_HEIGHT = 420;
const FEED_BESIDE_WIDTH = 600;

/**
 * Floor, chrome and feed rects for a CSS-pixel `width` × `height`. Scale is 1
 * at the 520×740 baseline and only grows (never shrinks) until the ~1.9 cap;
 * compact windows skip that growth so type stays a readable size.
 */
export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  const w = Math.max(320, width);
  const h = Math.max(240, height);
  const compact = w < COMPACT_WIDTH || h < COMPACT_HEIGHT;
  const feedBeside = w >= FEED_BESIDE_WIDTH;
  const fit = Math.min(w / BASE_WIDTH, h / BASE_HEIGHT);
  const scale = compact ? 1 : Math.min(SCALE_CAP, Math.max(1, fit));

  const gap = 6;
  const margin = 8;

  const topBarHeight = 38;
  const briefHeight = 32;
  const ticketsHeight = 72;

  const bodyX = margin;
  const briefY = margin + topBarHeight + gap;
  const bodyY = briefY + briefHeight + gap;

  const sideFeedWidth = feedBeside
    ? Math.max(170, Math.min(240, Math.round(w * 0.28)))
    : 0;
  const bodyWidth = feedBeside ? w - margin * 2 - gap - sideFeedWidth : w - margin * 2;
  const stackedFeedHeight = Math.max(110, Math.round(h * 0.2));
  const bodyBottom = feedBeside ? h - margin : h - margin - (stackedFeedHeight + gap);
  const bodyHeight = Math.max(120, bodyBottom - bodyY);

  const floorHeight = Math.max(90, bodyHeight - ticketsHeight - gap);

  const kitchenWidth = Math.round(bodyWidth * 0.25);
  const passWidth = Math.max(24, Math.round(bodyWidth * 0.07));
  const diningX = bodyX + kitchenWidth + gap + passWidth + gap;
  const diningWidth = Math.max(80, bodyX + bodyWidth - diningX);
  const doorHeight = Math.max(56, Math.round(floorHeight * 0.32));
  const diningHeight = floorHeight - doorHeight - gap;

  const kitchen = { x: bodyX, y: bodyY, width: kitchenWidth, height: floorHeight };
  const pass = { x: bodyX + kitchenWidth + gap, y: bodyY, width: passWidth, height: floorHeight };
  const dining = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door = { x: diningX, y: bodyY + diningHeight + gap, width: diningWidth, height: doorHeight };
  const labelH = 14;
  const hostGutter = 40;
  const standWidth = Math.min(90, Math.max(56, Math.round(door.width * 0.36)));
  const standHeight = Math.min(36, Math.max(22, door.height - labelH - 4));
  const doorStand = {
    x: door.x + hostGutter,
    y: door.y + labelH,
    width: Math.max(56, standWidth),
    height: Math.max(22, standHeight),
  };
  const spineY = pass.y + pass.height / 2;
  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: { x: kitchen.x + kitchen.width / 2, y: spineY },
    pass: { x: pass.x + pass.width / 2, y: spineY },
    floor: { x: dining.x + dining.width / 2, y: dining.y + dining.height / 2 },
    queue: { x: doorStand.x + doorStand.width / 2, y: doorStand.y + doorStand.height / 2 },
  };

  const feed = feedBeside
    ? { x: bodyX + bodyWidth + gap, y: bodyY, width: sideFeedWidth, height: Math.max(0, h - margin - bodyY) }
    : { x: margin, y: bodyBottom + gap, width: w - margin * 2, height: stackedFeedHeight };

  return {
    compact,
    scale,
    feedBeside,
    topBar: { x: margin, y: margin, width: w - margin * 2, height: topBarHeight },
