import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/** Linear hallway: kitchen — pass — floor — queue. Pass and floor are through-stations. */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

export const WALK_SPEED_PX_PER_SEC = 200;

export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const pending: WalkNode[] = [from];
  const cameFrom = new Map<WalkNode, WalkNode | undefined>([[from, undefined]]);
  while (pending.length > 0) {
    const current = pending.shift()!;
    if (current === to) break;
    for (const next of WALK_GRAPH[current]) {
      if (cameFrom.has(next)) continue;
      cameFrom.set(next, current);
      pending.push(next);
    }
  }
  if (!cameFrom.has(to)) return [from];
  const path: WalkNode[] = [];
  for (let node: WalkNode | undefined = to; node; node = cameFrom.get(node)) {
    path.push(node);
  }
  path.reverse();
  return path;
}

function samePoint(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y;
}

function pushPoint(points: Point[], point: Point): void {
  const last = points[points.length - 1];
  if (last && samePoint(last, point)) return;
  points.push({ x: point.x, y: point.y });
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let x = start.x;
  let y = start.y;

  const emit = (nx: number, ny: number) => {
    if (nx === x && ny === y) return;
    pushPoint(points, { x: nx, y: ny });
    x = nx;
    y = ny;
  };

  for (const node of nodes) {
    const dest = waypoints[node];
    if (!dest) continue;
    if (x === dest.x && y === dest.y) continue;
    if (x !== dest.x) {
      if (y !== spineY) emit(x, spineY);
      emit(dest.x, spineY);
    }
    if (y !== dest.y) emit(dest.x, dest.y);
  }

  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const dist = Math.hypot(to.x - from.x, to.y - from.y);
  if (dist <= 0) return 0;
  return (dist / WALK_SPEED_PX_PER_SEC) * 1000;
}

function easeInOutSine(t: number): number {
  return -(Math.cos(Math.PI * t) - 1) / 2;
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1;
  walking: boolean;
  dragging: boolean;
  node: WalkNode;

  private hops: Point[] = [];
  private hopFrom: Point = { x: 0, y: 0 };
  private hopTo: Point = { x: 0, y: 0 };
  private hopElapsed = 0;
  private hopDuration = 0;
  private hopIndex = -1;

  /** `slot` is the pixel position of `node`; the walker starts parked there. */
  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.x = slot.x;
    this.y = slot.y;
    this.facing = 1;
    this.walking = false;
    this.dragging = false;
  }

  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.walking = false;
    this.hops = [];
    this.hopIndex = -1;
    this.hopElapsed = 0;
    this.hopDuration = 0;
  }

  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    if (this.dragging) return;
    const path = bfsPath(this.node, target);
    this.node = target;
    this.hops = corridorPoints({ x: this.x, y: this.y }, path, waypoints, spineY);
    if (this.hops.length === 0) {
      this.walking = false;
      this.hopIndex = -1;
      return;
    }
    this.walking = true;
    this.hopIndex = 0;
    this.beginHop();
  }

  /** Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns whether the pixel position changed. */
  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking || speed <= 0 || dtMs <= 0) return false;
    const prevX = this.x;
    const prevY = this.y;
    let remaining = dtMs * speed;
    while (this.walking && remaining > 0) {
      if (this.hopIndex < 0 || this.hopIndex >= this.hops.length) {
        this.walking = false;
        break;
      }
      if (this.hopDuration <= 0) {
        this.finishHop();
        continue;
      }
      const left = this.hopDuration - this.hopElapsed;
      if (remaining >= left) {
        remaining -= left;
        this.x = this.hopTo.x;
        this.y = this.hopTo.y;
        this.finishHop();
      } else {
        this.hopElapsed += remaining;
        remaining = 0;
        const t = Math.min(1, this.hopElapsed / this.hopDuration);
        const eased = easeInOutSine(t);
        this.x = this.hopFrom.x + (this.hopTo.x - this.hopFrom.x) * eased;
        this.y = this.hopFrom.y + (this.hopTo.y - this.hopFrom.y) * eased;
      }
    }
    return this.x !== prevX || this.y !== prevY;
  }

  private beginHop(): void {
    const dest = this.hops[this.hopIndex];
    if (!dest) {
      this.walking = false;
      return;
    }
    this.hopFrom = { x: this.x, y: this.y };
    this.hopTo = dest;
    this.hopElapsed = 0;
    this.hopDuration = hopDurationMs(this.hopFrom, this.hopTo);
    if (this.hopTo.x > this.hopFrom.x) this.facing = 1;
    else if (this.hopTo.x < this.hopFrom.x) this.facing = -1;
  }

  private finishHop(): void {
    this.x = this.hopTo.x;
    this.y = this.hopTo.y;
    this.hopIndex += 1;
    if (this.hopIndex >= this.hops.length) {
      this.walking = false;
      this.hops = [];
      this.hopIndex = -1;
      return;
    }
    this.beginHop();
  }
}

/**
 * Holds scene repaints while a staff token is being dragged so a tick cannot
 * rebuild the floor and yank the token off the pointer. Resize cancels both
 * the drag and anything owed — the resize itself paints from scratch.
 */
export class RepaintGate {
  #dragging = false;
  #owed = false;

  constructor() {}

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.#dragging;
  }

  beginDrag(): void {
    this.#dragging = true;
  }

  /** Paints immediately (returns true) unless a drag is open, in which case the paint is held back (returns false) and one repaint becomes owed. */
  requestPaint(): boolean {
    if (this.#dragging) {
      this.#owed = true;
      return false;
    }
    return true;
  }

  /** Ends the drag. Returns whether a repaint was held back during it (and thus needs to be replayed by the caller now). */
  endDrag(): boolean {
    this.#dragging = false;
    const owed = this.#owed;
    this.#owed = false;
    return owed;
  }

  /** Drops any open drag and clears anything owed, since the resize itself repaints from scratch. */
  resize(): void {
    this.#dragging = false;
    this.#owed = false;
  }
}

