 * Holds scene repaints while a staff token is being dragged so a tick cannot
 * rebuild the floor and yank the token off the pointer. Resize cancels both
 * the drag and anything owed — the resize itself paints from scratch.
 */
export class RepaintGate {
  #dragging = false;
  #owed = false;

  constructor() {}

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.#dragging;
  }

  beginDrag(): void {
    this.#dragging = true;
  }

  /** Paints immediately (returns true) unless a drag is open, in which case the paint is held back (returns false) and one repaint becomes owed. */
  requestPaint(): boolean {
    if (this.#dragging) {
      this.#owed = true;
      return false;
    }
    return true;
  }

  /** Ends the drag. Returns whether a repaint was held back during it (and thus needs to be replayed by the caller now). */
  endDrag(): boolean {
    this.#dragging = false;
    const owed = this.#owed;
    this.#owed = false;
    return owed;
  }

  /** Drops any open drag and clears anything owed, since the resize itself repaints from scratch. */
  resize(): void {
    this.#dragging = false;
    this.#owed = false;
  }
}
