private stackedSlot(location: Location, offset: number, layout: RestaurantArenaLayout): { x: number; y: number } {
  const compact = layout.compact;
  const slot = layout.waypoints[location];
  const step = (compact ? 17 : 22) * layout.scale;
  return { x: slot.x + offset * step, y: slot.y };
}

private locationAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const hit = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  if (hit(layout.kitchen)) return "kitchen";
  if (hit(layout.pass)) return "pass";
  if (hit(layout.dining)) return "floor";
  if (hit(layout.doorStand) || hit(layout.door)) return "queue";
  return undefined;
}

private drawHallway(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
  const left = layout.kitchen.x + 6;
  const right = layout.dining.x + layout.dining.width - 6;
  g.lineStyle(2, 0x6a4a32, 0.4);
  g.lineBetween(left, layout.spineY, right, layout.spineY);
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  const offsets = new Map<Location, number>();
  this.staffTokens.clear();
  const seen = new Set<Role>();

  for (const worker of this.state.workers) {
    const location = this.visualLocation(worker);
    const offset = offsets.get(location) ?? 0;
    offsets.set(location, offset + 1);
    const slot = this.stackedSlot(location, offset, layout);
    seen.add(worker.role);

    let walker = this.walkers.get(worker.role);
    if (!walker) {
      walker = new StaffWalker(location, slot);
      this.walkers.set(worker.role, walker);
    } else if (walker.dragging) {
      // Pointer owns the token until drop; don't snap it back to a station.
    } else if (walker.node !== location) {
      walker.setTarget(location, layout.waypoints, layout.spineY);
    } else if (!walker.walking) {
      walker.snap(slot, location);
    }

    const token = this.buildAvatar(walker.x, walker.y, worker.role, worker.load, compact, layout.scale);
    const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
    figure?.setScale(walker.facing, 1);
    this.staffTokens.set(worker.role, token);
    const heldHost = worker.role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(worker.role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, worker.role, compact);
    this.wireStaffDrag(token, worker.role, location, slot, layout);
  }

  for (const role of [...this.walkers.keys()]) {
    if (!seen.has(role)) this.walkers.delete(role);
  }
}

private wireStaffDrag(
  token: Phaser.GameObjects.Container,
  role: Role,
  location: Location,
  slot: { x: number; y: number },
  layout: RestaurantArenaLayout,
): void {
  const unit = (layout.compact ? 2 : 2.6) * layout.scale;
  const hitW = unit * 10;
  const hitH = unit * 14;
  token.setSize(hitW, hitH);
  token.setInteractive(new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH), Phaser.Geom.Rectangle.Contains);
  if (token.input) token.input.cursor = "grab";
  this.input.setDraggable(token);

  token.on("dragstart", () => {
    const walker = this.walkers.get(role);
    if (!walker) return;
    this.gate.beginDrag();
    this.draggingRole = role;
    walker.dragging = true;
    walker.walking = false;
    this.tweens.killTweensOf(token);
    token.setDepth(50);
    if (token.input) token.input.cursor = "grabbing";
  });
  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    token.x = dragX;
    token.y = dragY;
    const walker = this.walkers.get(role);
    if (!walker) return;
    if (dragX > walker.x) walker.facing = 1;
    else if (dragX < walker.x) walker.facing = -1;
    walker.x = dragX;
    walker.y = dragY;
    const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
    figure?.setScale(walker.facing, 1);
  });
  token.on("dragend", () => {
    const walker = this.walkers.get(role);
    this.draggingRole = undefined;
    if (walker) walker.dragging = false;
    if (token.input) token.input.cursor = "grab";
    const drop = this.locationAt(token.x, token.y, layout);
    if (walker && drop && drop !== location) {
      walker.setTarget(drop, layout.waypoints, layout.spineY);
      this.onAction(`assign_${role}_${drop}`);
    } else if (walker) {
      walker.snap(slot, location);
      token.setPosition(walker.x, walker.y);
    }
    if (this.gate.endDrag()) this.paint();
  });
}

update(_time: number, delta: number): void {
  const layout = this.lastLayout;
  if (!layout) return;
  const speed = this.state.sim?.running ? (this.state.sim.speed ?? 1) : 0;
  for (const [role, walker] of this.walkers) {
    if (walker.dragging) continue;
    const moved = walker.step(delta, speed);
    const token = this.staffTokens.get(role);
    if (!token) continue;
    if (moved) token.setPosition(walker.x, walker.y);
    const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
    figure?.setScale(walker.facing, 1);
  }
}

