import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout, type ArenaRect } from "./restaurant-arena-layout.js";

function inside(rect: ArenaRect, width: number, height: number): boolean {
  return rect.x >= 0 && rect.y >= 0 && rect.x + rect.width <= width + 1e-6 && rect.y + rect.height <= height + 1e-6;
}

describe("restaurantArenaLayout", () => {
  test("is scale 1 at the 520×740 baseline, not compact, feed stacked", () => {
    const layout = restaurantArenaLayout(520, 740);
    expect(layout.scale).toBe(1);
    expect(layout.compact).toBe(false);
    expect(layout.feedBeside).toBe(false);
    expect(layout.feed.y).toBeGreaterThan(layout.tickets.y);
    expect(layout.spineY).toBeGreaterThanOrEqual(layout.pass.y);
    expect(layout.spineY).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
  });

  test("stays compact and does not grow text below ~460 wide or ~420 tall", () => {
    expect(restaurantArenaLayout(459, 740).compact).toBe(true);
    expect(restaurantArenaLayout(459, 740).scale).toBe(1);
    expect(restaurantArenaLayout(520, 419).compact).toBe(true);
    expect(restaurantArenaLayout(520, 419).scale).toBe(1);
    expect(restaurantArenaLayout(460, 420).compact).toBe(false);
  });

  test("grows with the smaller of width/520 and height/740, capped near 1.9", () => {
    const grown = restaurantArenaLayout(1040, 1480);
    expect(grown.compact).toBe(false);
    expect(grown.scale).toBeCloseTo(1.9, 5);
    const limitedByHeight = restaurantArenaLayout(2000, 1110);
    expect(limitedByHeight.scale).toBeCloseTo(1110 / 740, 5);
    const limitedByWidth = restaurantArenaLayout(780, 2000);
    expect(limitedByWidth.scale).toBeCloseTo(780 / 520, 5);
  });

  test("sits the feed beside the floor once the window is ~600px+ wide", () => {
    const stacked = restaurantArenaLayout(599, 740);
    expect(stacked.feedBeside).toBe(false);
    const beside = restaurantArenaLayout(600, 740);
    expect(beside.feedBeside).toBe(true);
    expect(beside.feed.x).toBeGreaterThan(beside.kitchen.x + beside.kitchen.width);
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.dining.x + beside.dining.width - 1e-6);
    expect(beside.feed.y).toBeLessThan(beside.tickets.y + beside.tickets.height);
  });

  test("keeps doorStand at least 56×22 and queue on it, floor in dining", () => {
    for (const [w, h] of [
      [320, 240],
      [520, 740],
      [720, 780],
      [1200, 900],
    ] as const) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.doorStand.width).toBeGreaterThanOrEqual(56);
      expect(layout.doorStand.height).toBeGreaterThanOrEqual(22);
      const { queue, floor } = layout.waypoints;
      expect(queue.x).toBeGreaterThanOrEqual(layout.doorStand.x);
      expect(queue.x).toBeLessThanOrEqual(layout.doorStand.x + layout.doorStand.width);
      expect(queue.y).toBeGreaterThanOrEqual(layout.doorStand.y);
      expect(queue.y).toBeLessThanOrEqual(layout.doorStand.y + layout.doorStand.height);
      expect(floor.x).toBeGreaterThanOrEqual(layout.dining.x);
      expect(floor.x).toBeLessThanOrEqual(layout.dining.x + layout.dining.width);
      expect(floor.y).toBeGreaterThanOrEqual(layout.dining.y);
      expect(floor.y).toBeLessThanOrEqual(layout.dining.y + layout.dining.height);
    }
  });

  test("fits every rect inside the requested width and height", () => {
    const layout = restaurantArenaLayout(720, 780);
    const width = Math.max(320, 720);
    const height = Math.max(240, 780);
    for (const rect of [
      layout.topBar,
      layout.brief,
      layout.kitchen,
      layout.pass,
      layout.dining,
      layout.door,
      layout.doorStand,
      layout.tickets,
      layout.feed,
    ]) {
      expect(inside(rect, width, height)).toBe(true);
    }
  });
});

import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
} from "./staff-walk.js";

describe("staff walk graph", () => {
  test("wires kitchen-pass-floor-queue as one hallway with pass and floor as through-stations", () => {
    expect(WALK_GRAPH.kitchen).toEqual(["pass"]);
    expect(WALK_GRAPH.pass).toEqual(["kitchen", "floor"]);
    expect(WALK_GRAPH.floor).toEqual(["pass", "queue"]);
    expect(WALK_GRAPH.queue).toEqual(["floor"]);
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
    expect(bfsPath("kitchen", "kitchen")).toEqual(["kitchen"]);
  });

  test("corridorPoints rides the hallway instead of cutting diagonally", () => {
    const layout = restaurantArenaLayout(520, 740);
    const start = layout.waypoints.kitchen;
    const path = corridorPoints(start, ["kitchen", "pass", "floor", "queue"], layout.waypoints, layout.spineY);
    expect(path.at(-1)).toEqual(layout.waypoints.queue);
    for (let i = 1; i < path.length; i++) {
      const a = path[i - 1]!;
      const b = path[i]!;
      expect(a.x === b.x || a.y === b.y).toBe(true);
    }
    expect(path.some((point) => point.y === layout.spineY)).toBe(true);
    const kitchenToPass = corridorPoints(start, ["pass"], layout.waypoints, layout.spineY);
    for (const point of kitchenToPass) {
      expect(point.y).toBe(layout.spineY);
    }
  });

  test("hopDurationMs is 200px per second", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 0 })).toBe(0);
  });

  test("StaffWalker parks, snaps, walks, pauses, and eases each hop", () => {
    const layout = restaurantArenaLayout(520, 740);
    const walker = new StaffWalker("kitchen", layout.waypoints.kitchen);
    expect(walker.x).toBe(layout.waypoints.kitchen.x);
    expect(walker.y).toBe(layout.waypoints.kitchen.y);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.facing).toBe(1);

    walker.snap(layout.waypoints.pass, "pass");
    expect(walker.node).toBe("pass");
    expect(walker.x).toBe(layout.waypoints.pass.x);
    expect(walker.walking).toBe(false);

    walker.snap(layout.waypoints.kitchen, "kitchen");
    walker.setTarget("queue", layout.waypoints, layout.spineY);
    expect(walker.walking).toBe(true);
    expect(walker.node).toBe("queue");

    const frozenX = walker.x;
    const frozenY = walker.y;
    expect(walker.step(16, 0)).toBe(false);
    expect(walker.x).toBe(frozenX);
    expect(walker.y).toBe(frozenY);

    walker.dragging = true;
    expect(walker.step(100, 1)).toBe(false);
    walker.dragging = false;

    const hops = corridorPoints(layout.waypoints.kitchen, bfsPath("kitchen", "queue"), layout.waypoints, layout.spineY);
    const first = hops[0]!;
    const hopMs = hopDurationMs(layout.waypoints.kitchen, first);
    walker.step(hopMs * 0.25, 1);
    const linear = {
      x: layout.waypoints.kitchen.x + (first.x - layout.waypoints.kitchen.x) * 0.25,
      y: layout.waypoints.kitchen.y + (first.y - layout.waypoints.kitchen.y) * 0.25,
    };
    const movedOffLinear =
      Math.abs(walker.x - linear.x) > 0.01 || Math.abs(walker.y - linear.y) > 0.01;
    expect(movedOffLinear || hopMs === 0).toBe(true);

    for (let i = 0; i < 400; i++) walker.step(50, 1);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(layout.waypoints.queue.x);
    expect(walker.y).toBe(layout.waypoints.queue.y);
  });
});

import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints immediately when no drag is open", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("holds paints during a drag and owes exactly one repaint on endDrag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("endDrag returns false when nothing was owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  test("resize drops an open drag and clears anything owed so a stray dragend paints nothing", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.requestPaint()).toBe(false);
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });
});

